105	    /// Register one parser type that exposes a static `create()` constructor.
106	    pub fn register_parser<T>(&mut self, name: &str) -> &mut Self
107	    where
108	        T: ToolParser + 'static,
109	    {
110	        self.register_creator(name, T::create)
111	    }
