169	/// Parse a JSON tool-call event for the current parser mode.
170	fn parse_next_json_tool_call_event(
171	    input: &mut JsonToolInput<'_>,
172	    mode: &mut JsonToolCallMode,
173	    config: JsonToolCallConfig,
174	) -> ModalResult<JsonToolCallEvent> {
175	    match mode {
176	        JsonToolCallMode::Text => parse_text_event(input, config),
177	        JsonToolCallMode::Header => tool_call_header_event(input, config),
178	        JsonToolCallMode::Arguments { json_scan } => {
179	            parse_arguments_event(input, json_scan, config)
180	        }
181	    }
182	}
183	
184	/// Parse a text-mode JSON tool-call event.
185	fn parse_text_event(
186	    input: &mut JsonToolInput<'_>,
187	    config: JsonToolCallConfig,
188	) -> ModalResult<JsonToolCallEvent> {
189	    alt((
190	        |input: &mut JsonToolInput<'_>| tool_call_start_event(input, config),
191	        |input: &mut JsonToolInput<'_>| safe_text_event(input, config),
192	    ))
193	    .parse_next(input)
194	}
195	
196	/// Parse a marker-wrapped JSON tool-call start marker.
197	fn tool_call_start_event(
198	    input: &mut JsonToolInput<'_>,
199	    config: JsonToolCallConfig,
200	) -> ModalResult<JsonToolCallEvent> {
201	    seq!(
202	        _: literal(config.start_marker),
203	        _: |input: &mut JsonToolInput<'_>| marker_whitespace(input, config),
204	    )
205	    .value(JsonToolCallEvent::ToolCallStart)
206	    .parse_next(input)
207	}
208	
209	/// Parse a marker-wrapped JSON tool-call header before the raw arguments
210	/// payload.
211	fn tool_call_header_event(
212	    input: &mut JsonToolInput<'_>,
213	    config: JsonToolCallConfig,
214	) -> ModalResult<JsonToolCallEvent> {
215	    let (function_name,) = seq!(
216	        _: ws0,
217	        _: literal("{"),
