221	        _: literal(":"),
222	        _: ws0,
223	        json_str,
224	        _: ws0,
225	        _: literal(","),
226	        _: ws0,
227	        _: |input: &mut JsonToolInput<'_>| json_key(input, config.arguments_key),
228	        _: ws0,
229	        _: literal(":"),
230	        _: ws0,
231	    )
